  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''DELEGATED_ORCHESTRATION_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''DELEGATED_ORCHESTRATION_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''DELEGATED_ORCHESTRATION_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''DELEGATED_ORCHESTRATION_APP'' AND "comment"=''oneshot-source:28_delegated_orchestration''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.DELEGATED_ORCHESTRATION_APP FROM ''@__TARGET__.APP_STAGE/source/80dd430448025dc3/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:28_delegated_orchestration''; ALTER STREAMLIT __TARGET__.DELEGATED_ORCHESTRATION_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
