          statement_index := :statement_index+1;
        END WHILE;
      ELSEIF (:existing_app[0]:comment::VARCHAR NOT IN ('oneshot-source:28_delegated_orchestration','Zero-Privilege Orchestration — generated from account discovery','Observability Monitor - generated from account discovery')) THEN
